<?php
declare(strict_types=1);namespace Vendi\Payments;use PDO;use RuntimeException;use Vendi\Support\Money;
final class PaymentProcessor{public function __construct(private PDO$db){}
 public function validate(int$b,int$branch,array$payments,float$total,bool$quick=false):array{if(!$payments)throw new RuntimeException('Agrega un método de pago.');$out=[];$sum=0;$cashChangeAllowed=false;foreach($payments as$p){$id=(int)($p['payment_method_id']??0);if(!$id)throw new RuntimeException('Método de pago inválido.');$q=$this->db->prepare("SELECT pm.id,pm.code,pm.name,pm.type,pm.affects_cash_drawer,pm.allows_change,pm.requires_reference,pm.quick_compatible FROM payment_methods pm LEFT JOIN branch_payment_methods bpm ON bpm.payment_method_id=pm.id AND bpm.branch_id=? WHERE pm.id=? AND pm.business_id=? AND pm.active=1 AND COALESCE(bpm.enabled,1)=1 LIMIT 1");$q->execute([$branch,$id,$b]);$m=$q->fetch();if(!$m)throw new RuntimeException('Método de pago no disponible en esta sucursal.');if($quick&&(!(int)$m['quick_compatible']||(int)$m['requires_reference']))throw new RuntimeException('El método configurado no admite venta rápida.');$amount=Money::round((float)($p['amount']??0));if($amount<=0)throw new RuntimeException('Importe de pago inválido.');$ref=trim((string)($p['reference']??''));if((int)$m['requires_reference']&&$ref==='')throw new RuntimeException('Captura la referencia de '.$m['name'].'.');$sum+=$amount;$cashChangeAllowed=$cashChangeAllowed||((int)$m['allows_change']===1);$out[]=['payment_method_id'=>(int)$m['id'],'method'=>$m['type'],'code'=>$m['code'],'name'=>$m['name'],'amount'=>$amount,'reference'=>$ref?:null,'affects_cash_drawer'=>(bool)$m['affects_cash_drawer'],'allows_change'=>(bool)$m['allows_change']];}if(Money::round($sum)<Money::round($total))throw new RuntimeException('Pago insuficiente.');$change=Money::round($sum-$total);if($change>0&&!$cashChangeAllowed)throw new RuntimeException('El importe excede el total y ningún método permite cambio.');$remaining=$change;foreach($out as &$line){$line['change_amount']=0.0;if($remaining>0&&$line['allows_change']){$take=min($remaining,$line['amount']);$line['change_amount']=Money::round($take);$remaining=Money::round($remaining-$take);}}unset($line);if($remaining>0)throw new RuntimeException('No fue posible asignar el cambio a un método permitido.');return['payments'=>$out,'paid'=>Money::round($sum),'change'=>$change];}
}